"""Generate the stage-1 report from the verified T0037 backup; no games run."""
import argparse, collections, hashlib, json, shutil
from pathlib import Path

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--backup',type=Path,required=True);args=ap.parse_args()
    source=args.backup/'t0037';out=Path(__file__).resolve().parent
    manifest=json.loads((source/'BACKUP_MANIFEST_20261012.json').read_text())
    for name,info in manifest['files'].items():
        data=(source/name).read_bytes()
        assert len(data)==info['bytes'] and hashlib.sha256(data).hexdigest()==info['sha256'],name
    rows=[json.loads(p.read_text()) for p in sorted((source/'data/rows').glob('*.json'))]
    matches=list((source/'data/matches').rglob('*.json.gz'))
    report=json.loads((source/'report/run.json').read_text())
    assert len(rows)==len(matches)==report['games']==306
    assert collections.Counter(r['teams'] for r in rows)=={n:34 for n in range(2,11)}
    assert len({r['fixture_id'] for r in rows})==306
    assert not list((source/'data/errors').glob('*.json'))
    bad=[]
    for r in rows:
        for seat,f in enumerate(r['faults']):
            if f['faults'] or f['late'] or f['dead']:
                bad.append({'fixture_id':r['fixture_id'],'seat':seat,'name':f['name'],'faults':f['faults'],'late':f['late'],'dead':f['dead']})
    assert sum(x['faults'] for x in bad)==2
    for n,d in report['per_count'].items():
        rr=[r for r in rows if r['teams']==int(n)]
        assert sum(f['faults'] for r in rr for f in r['faults'])==d['seat_faults']
        assert sum(d['selected_root_strata'].values())==d['roots']==34
    for p in sorted((source/'report').glob('*.json')):shutil.copyfile(p,out/p.name)
    shutil.copyfile(source/'BACKUP_MANIFEST_20261012.json',out/'BACKUP_MANIFEST.json')
    shutil.copyfile(source/'probe.py',out/'probe.py')
    receipt=json.loads((args.backup/'VERIFIED.json').read_text());receipt.update(fault_seats=bad,stage='whole-match collection only; branch continuations pending')
    (out/'BACKUP_VERIFIED.json').write_text(json.dumps(receipt,indent=2)+'\n')
    probes=json.loads((out/'probe_feasibility.json').read_text())
    lines=['# T0037 Colab stage-1 collection report','', 'Generated by `generate_report.py` from the verified backup. Original Colab receipts are retained byte-for-byte.','',
    '## Scope and status','',
    '**Whole-match collection is complete; the decision-branch pilot is incomplete.** This report covers preflight, the admitted opponent pool, sampler, 306 complete matches and root availability. It does not close T0037 or unlock T0038. Candidate continuations, repeated-outcome noise and learnability remain unmeasured; the branch stage waits for T0040 / PR #36. No training, export, production change or playing-strength claim.','',
    'All timing and fault observations below belong to a Google Colab CPU runtime, not the target Windows host. Counts 11–15 failed the declared Colab feasibility gate and were not collected. Passing two recorded probes is not a guarantee: the collection later retained two faults at count 9.','',
    '## Frozen experiment','',
    '- Source: `41022c0e47a63afba11ee33acda7dd79ebc298ea`; engine: `54139d4ebf723fb5b6a25044d242dd0575eceaf1`.','- Runtime: AMD EPYC 7B12, 2 vCPUs, 12 GB RAM, Python 3.13.16, g++ 13.3.0, no GPU.','- Official first/turn limits: 2000/50 ms; one collection worker, frozen before collection.','- Carrier: `v12_ponly_xxl_dlog`, P2 XXL, V off; binary SHA-256 `9d713366c6a2bb285244c5d381f8e0b726560ef44a1d468a15e7f3281782d281`.','- Pool identity: `0e2bfcf6d151c984`; full-schedule frozen identity: `ff7872ab7e90d0dc`; pilot frozen identity: `06b5ccacdafe75ab`. Full identities are in the receipts.','- Training-only seed **20261501 is consumed**. Initially 336 fixtures (24 each, 2–15); redeclared before games as 306 fixtures (34 each, 2–10). The overlapping 216 fixtures are identical.','- Pilot schedule identity: `1d80e761c27c88e4`. The raw schedule file SHA-256 is `5224cfb71a4e28164af143286f53dc96789a1693a97709ee3de76e06dd47c309`.','',
    '## Availability and preflight','',
    'The registry contains 52 enabled opponents (12 reference, 6 addition, 34 neural), five missing-weight A–E entries with zero sampling, and seven excluded roles. The decision-log carriers are excluded from opponents. Availability, resolutions, model/source inputs and binary identities are retained in `registry.json`, `availability.json` and `FROZEN.json`. Sampler simulation and realized component, neural-group and lineage masses are in `sampler.json`; realized proportions differ by count and should not be described as exact target weights.','',
    'The gate required zero faults and zero late replies across every seat in both sampled recorded-input compositions. All seats ran concurrently; replies were not applied. The recorded states and two compositions per count provide a bounded load probe, not exhaustive admission across all compositions.','',
    '| Teams | Probe faults (two compositions) | Worst observed max reply ms | Colab gate |','|---|---|---|---|']
    for n in range(2,16):
        rr=[r for r in probes if r['teams']==n]
        lines.append(f"| {n} | {', '.join(str(r['faults']) for r in rr)} | {max(r['worst_max_ms'] for r in rr):.3f} | {'pass' if all(r['faults']==r['late']==0 and not r['dead'] for r in rr) else 'fail'} |")
    lines+=['','A/A used one recorded 4-team match, seat 0 and Baseline in other seats: v12 and the hooked carrier each reproduced 400/400 orders; carrier versus production v12 matched 400/400. C08 A/A matched 98%; v12 versus C08 matched 42.2%. These are limited response/stability checks, not proof of equivalence under every load or group-wide diversity. Details: `probe_aa.json`.','',
    '## Whole-match coverage','',
    '| Teams | Maps | Usable roots | Faults | Cut turns / all carrier turns |','|---|---|---|---|---|']
    for n,d in sorted(report['per_count'].items(),key=lambda x:int(x[0])):
        lines.append(f"| {n} | {d['games']} | {d['roots']} | {d['seat_faults']} | {d['stages'].get('cut',0)} / {sum(d['stages'].values())} |")
    strata=collections.Counter()
    for d in report['per_count'].values():strata.update(d['selected_root_strata'])
    lines+=['',f"Selected-root strata: {dict(strata)}. `run.json` also retains observable-stratum opportunities, logged per-turn K, root rejection reasons and stage counts. Root selection follows the frozen collector's deterministic hash over eligible logged turns; it does not optimize final outcome or enforce stratum quotas. A usable root is not yet a completed branch label. Actual selected candidate K and repeat coverage must be reported after continuation collection.",'',
    'There were zero collection error records, zero reported late replies and zero dead bots. Fixture `s20261501-n09-m00032` retained one C08 fault and one designated-carrier fault. No failed seat or fixture was silently removed. Match utility means in the original receipts are descriptive collection outputs, not paired strength evidence.','',
    '## Backup and continuation','',
    f"Archive `T0037_colab_seed20261501_20261012.tar.gz`: {receipt['bytes']} bytes; SHA-256 `{receipt['archive_sha256']}`. All {receipt['verified_files']} archived payload file hashes were verified locally, with 306 match files and 306 row files. The local archive and extracted copy reside in the Player5 workspace backup directory; cloud synchronization has not been confirmed. Raw data and rebuildable binaries are not committed. `BACKUP_MANIFEST.json` records payload hashes; `BACKUP_VERIFIED.json` records the verification result. The archive excludes rebuildable binaries and Python bytecode but retains build manifests.",'',
    'Reproduce report preparation: `python bots/p_only/report/decision_collection/colab_20261012/generate_report.py --backup <backup-directory>` (the directory contains `t0037/` and `VERIFIED.json`). This verifies source hashes before copying original receipts and generating this report. No new seed is consumed.','',
    'Next: review/merge T0040, restore the archived matches and frozen inputs, preserve original match hashes and carrier binaries, and freeze separate branch-collector code provenance. Collect one root/map, incumbent plus up to three legal logged alternatives, initially four live continuations/candidate. Record selected K, prefix/root/continuation faults, repeat/internal-state provenance and any drops. Do not pool with host data or reinterpret deterministic repeats as independent evidence. Complete the noise audit and remaining T0037 acceptance criteria before closing the task.','']
    (out/'RESULTS.md').write_text('\n'.join(lines))
    print('Verified backup and generated stage-1 report:',len(rows),'matches')
if __name__=='__main__':main()
